}

for (const [index, lineItem] of table.table_cp.entries()) {
  lineItem.invoice_total = formatNumber(lineItem.invoice_total);
  lineItem.paid_amount = formatNumber(lineItem.paid_amount);
  lineItem.outstanding_amount = formatNumber(lineItem.outstanding_amount);
  lineItem.line_status = lineItem.line_status !== 'Reversed' ? {{workflowparams:saveAs}} : lineItem.line_status
}

table.total_payment_amount = formatNumber(table.total_payment_amount);
