    cp_no: {{node:code_node_XjIiID3L.data.table.cp_no}},
    payment_date: {{node:code_node_XjIiID3L.data.table.payment_date}},
    payment_description: {{node:code_node_XjIiID3L.data.table.payment_description}},
    customer_id: {{node:code_node_XjIiID3L.data.table.customer_id}},
    payment_currency: {{node:code_node_XjIiID3L.data.table.payment_currency}},
    total_payment_amount: {{node:code_node_XjIiID3L.data.table.total_payment_amount}},
    cust_payment_method: {{node:code_node_XjIiID3L.data.table.cust_payment_method}}

  })
}

const allData = {{node:code_node_XjIiID3L.data.table}};
let status = "Success";
let msg = "";

if (parseFloat(allData.total_payment_amount) <= 0) {
  return {
    status: "Failed",
    msg: "Total payment amount cannot be negative or zero",
  };
}

if (parseFloat(allData.unallocated_amount) < 0) {
  return {
    status: "Failed",
    msg: "Total allocated amount cannot exceed total payment amount",
  };
}

return {
  status,
  msg,
};

const formatNumber = (value) => {
  if (value === null || value === undefined || value === "") return "0.00000000";
  return parseFloat(value).toFixed(8);
};

const round8 = (value) => {
  return Math.round((parseFloat(value) || 0) * 100000000) / 100000000;
};


const tableCP = {{workflowparams:allData.table_cp}};
const tablesiList = {{workflowparams:allData.table_silist}} || [];

// Get latest allocated SI
const latestAllocatedSI = tableCP.map((item) => {
  return {
    si_id: item.invoice_id,
    outstanding_amount: formatNumber(item.outstanding_amount),
    payment_status: round8(item.outstanding_amount) <= 0 ? 'Paid' : round8(item.outstanding_amount) !== round8(item.invoice_total) ? 'Partial' : 'Unpaid'
  }
})

// Get latest remove allocated SI
const latestUnpaidSI = tablesiList.map((item) => {
  if(round8(item.si_paid_amount) > 0) {
    const matchedSI = tableCP.find(si => si.invoice_id === item.si_invoice_id);

    if(!matchedSI) {
      const latestOutstandingAmount = round8(item.si_outstanding_amount) + round8(item.si_paid_amount);
      return {
        si_id: item.si_invoice_id,
        outstanding_amount: formatNumber(latestOutstandingAmount),
        payment_status: latestOutstandingAmount < round8(item.si_invoice_total) ? 'Partial' : 'Unpaid'
      }
    }
  }
})


return {
  updatedSI: [...latestAllocatedSI, ...latestUnpaidSI]
}

const allData = {{workflowparams:allData}};
const previousTotal = parseFloat(allData.previous_total);
const totalPayment = parseFloat(allData.total_payment_amount);
const saveAs = {{workflowparams:saveAs}};

if(previousTotal !== totalPayment && saveAs == 'Completed') {
  return {
    reversed: 'Reversed CP'
  }
} else {
  return {
    reversed: 'Reversed Line'
  }
}

const formatNumber = (value) => {
  if (value === null || value === undefined || value === "") return "0.00000000";
  return parseFloat(value).toFixed(8);
};

const round8 = (value) => {
  return Math.round((parseFloat(value) || 0) * 100000000) / 100000000;
};

const existingCPLine = {{node:get_node_k8wOItGL.data.data.table_cp}};
const currentCPLine = {{node:code_node_XjIiID3L.data.table.table_cp}};

let updatedSI = [];

// Update latest SI outstanding based on existing CP line and current CP line
const latestExistingCPLine = existingCPLine.map((lineItem) => {
  const matchedCurrentCPLine = currentCPLine.find(
    (item) => item.invoice_id === lineItem.invoice_id,
  );

  // If there is a matched line in current CP line
  if (matchedCurrentCPLine) {
    // If paid amount is changed, recalculate outstanding and set status to 'Reversed'
    if (
      round8(matchedCurrentCPLine.paid_amount) !==
      round8(lineItem.paid_amount)
    ) {
      const latestOutstandingAmount = round8(
        lineItem.outstanding_amount +
          lineItem.paid_amount -
          matchedCurrentCPLine.paid_amount,
      );

      updatedSI.push({
        si_id: lineItem.invoice_id,
        outstanding_amount: formatNumber(latestOutstandingAmount),
        payment_status:
          latestOutstandingAmount === round8(lineItem.invoice_total)
            ? "UnPaid"
            : latestOutstandingAmount == 0
              ? "Paid"
              : "Partial",
      });

      return {
        ...lineItem,
        line_status: "Reversed",
      };
    } else {
      // Paid amount unchanged - reversed the line
      return {
        ...lineItem,
        line_status: "Reversed",
      };
    }
  } else {
    // No matched line in current CP - invoice removed, reverse it
    const latestOutstandingAmount = round8(
      lineItem.outstanding_amount + lineItem.paid_amount,
    );

    updatedSI.push({
      si_id: lineItem.invoice_id,
      outstanding_amount: formatNumber(latestOutstandingAmount),
      payment_status:
        latestOutstandingAmount === round8(lineItem.invoice_total)
          ? "UnPaid"
          : latestOutstandingAmount == 0
            ? "Paid"
            : "Partial",
    });

    return {
      ...lineItem,
      line_status: "Reversed",
    };
  }
});

return {
  updatedSI,
  latestExistingCPLine,
  currentCPLine: currentCPLine.filter((item) => item.line_status !== "Reversed"),
};

const formatNumber = (value) => {
  if (value === null || value === undefined || value === "") return "0.00000000";
  return parseFloat(value).toFixed(8);
};

const round8 = (value) => {
  return Math.round((parseFloat(value) || 0) * 100000000) / 100000000;
};


let existingCPLine = {{node:get_node_ICF1dk1N.data.data.table_cp}};
let currentCPLine = {{node:code_node_XjIiID3L.data.table.table_cp}}.filter((item) => item.line_status !== "Reversed");

let updatedSI = [];

// Update latest exisiting CP line based on existing CP line and current CP line
const latestExistingCPLine = existingCPLine.map((lineItem) => {
  if (lineItem.line_status !== "Reversed") {
    const matchedCurrentCPLine = currentCPLine.find(
      (item) => item.invoice_id === lineItem.invoice_id,
    );

    // If there is a matched line in current CP line,
    // if the paid amount is changed, we will recalculate the outstanding amount and set the line_status as 'Reversed'
    if (matchedCurrentCPLine) {
      if (
        round8(matchedCurrentCPLine.paid_amount) !==
        round8(lineItem.paid_amount)
      ) {
        const latestOutstandingAmount = round8(
          lineItem.outstanding_amount +
            lineItem.paid_amount -
            matchedCurrentCPLine.paid_amount,
        );

        updatedSI.push({
          si_id: lineItem.invoice_id,
          outstanding_amount: formatNumber(latestOutstandingAmount),
          payment_status:
            latestOutstandingAmount === round8(lineItem.invoice_total)
              ? "UnPaid"
              : latestOutstandingAmount == 0
                ? "Paid"
                : "Partial",
        });

        return {
          ...lineItem,
          line_status: "Reversed",
        };
      } else {
        return lineItem;
      }
    }

    // If there is no matched line in current CP line, it means the invoice is removed in current CP, then set the line_status as 'Reversed' and outstanding amount will be increased by paid amount
    else {
      const latestOutstandingAmount = round8(
        lineItem.outstanding_amount + lineItem.paid_amount,
      );

      updatedSI.push({
        si_id: lineItem.invoice_id,
        outstanding_amount: formatNumber(latestOutstandingAmount),
        payment_status:
          latestOutstandingAmount === round8(lineItem.invoice_total)
            ? "UnPaid"
            : latestOutstandingAmount == 0
              ? "Paid"
              : "Partial",
      });

      return {
        ...lineItem,
        line_status: "Reversed",
      };
    }
  } else {
    return lineItem;
  }
});

// For the line in current CP line, 
// if there is no matched line in existing CP line, it means it's a new invoice added in current CP, then we will add this line to latest CP line and outstanding amount will be decreased by paid amount
currentCPLine.forEach((lineItem) => {
  const matchedExistingCPLine = existingCPLine.find(
    (item) => item.invoice_id === lineItem.invoice_id && item.line_status !== "Reversed",
  );

  if (!matchedExistingCPLine) {
    const latestOutstandingAmount = round8(
      lineItem.outstanding_amount - lineItem.paid_amount,
    );

    updatedSI.push({
      si_id: lineItem.invoice_id,
      outstanding_amount: formatNumber(latestOutstandingAmount),
      payment_status:
        latestOutstandingAmount === round8(lineItem.invoice_total)
          ? "UnPaid"
          : latestOutstandingAmount == 0
            ? "Paid"
            : "Partial",
    });
  }

  // if there is a matched line in existing CP line, check the paid amount,
  // if the paid amount is unchanged, then remove the line from current CP line to avoid duplicated line in latest CP line
  // if the paid amount is changed, then remove the id from current CP line
  else {
    if (
      round8(lineItem.paid_amount) ===
        round8(matchedExistingCPLine.paid_amount)
    ) {
      const index = currentCPLine.findIndex(
        (item) => item.invoice_id === lineItem.invoice_id,
      );
      if (index > -1) {
        currentCPLine.splice(index, 1);
      }
    } else {
      lineItem.id = "";
    }
  }
});

// The latest CP line will be the combination of the updated existing CP line and the new line in current CP line
const latestCPLine = [...latestExistingCPLine, ...currentCPLine];

return {
  latestCPLine,
  updatedSI,
};
